ndencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-ui-commands\": \"^0.1.7-rc.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"^0.1.7-rc.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"^0.1.7-rc.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.7-rc.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.7-rc.1 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.4\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-commands\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-renderer\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-settings\": \"^0.1.7-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.7-rc.1\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-commands\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\",\n        \"@deepseek-ai/dsh-client-ui-renderer\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"engines\": {\n      \"dsh\": \">=0.1.7-rc.1\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.1.7-rc.1\": \"compatible\"\n      }\n    }\n  }\n}\n"
